import { Component, OnInit } from "@angular/core";
import { Observable } from "rxjs";
import { AuthService } from "app/core/services/auth.service";
import { HistoryService } from "app/core/services/history.service";

export interface CurrentUser {
  username: string;
  email: string;
  name: string;
}

@Component({
  selector: "app-header",
  templateUrl: "./header.component.html"
})
export class HeaderComponent implements OnInit {

  currentUser$!: Observable<CurrentUser | null>;

  constructor(
    private authService: AuthService,
    private historyService: HistoryService
  ) {}

  ngOnInit(): void {
    this.currentUser$ = this.authService.currentUser$;
  }

  logout(): void {
    this.historyService.clearSession();
    this.authService.logout();
  }
}
<header class="app-header">
  <span class="header-title" routerLink="/measure" style="cursor: pointer;">Quantity Measurement App</span>

  <div class="header-user">
    <!-- async pipe subscribes to currentUser$ and auto-unsubscribes -->
    <ng-container *ngIf="currentUser$ | async as user; else guestTpl">
      <span class="header-username">{{ user.username }}</span>
      <button class="btn-logout" (click)="logout()">Logout</button>
    </ng-container>

    <ng-template #guestTpl>
      <a routerLink="/auth/login" class="btn-logout" style="text-decoration:none">Login</a>
    </ng-template>
  </div>
</header>
